def _resolve_store_file(store_path: str | Path) -> Path
"""Resolve a store argument to the actual JSON file path."""
def _resolve_store_file(store_path: str | Path) -> Path:
    """Resolve a store argument to the actual JSON file path."""
    path = Path(store_path)
    if path.is_dir():
        return path / KnowledgeStore.DEFAULT_FILENAME
    if path.suffix == ".json":
        return path
    return path / KnowledgeStore.DEFAULT_FILENAME

